def is_Sub_Array(A, B):
    n = len(A)
    m = len(B)
    i = 0
    while i <= m - n:
        j = 0
        while j < n and i + j < m:
            if A[j] != B[i + j]:
                break
            j += 1
        if j == n:
            return True
        i += 1
    return False

